    q("DSAQ058", "COMP-DSA-SEARCH", "DSA-SEARCH-SORT", "scenario", "analysis", 2.0, "You binary-search the minimum feasible capacity. What property must the feasibility predicate have over increasing capacities?", [("A", "It must alternate between true and false."), ("B", "Once true, it must remain true for larger capacities."), ("C", "It must be true for exactly one capacity."), ("D", "It must compare only adjacent input elements.")], ["B"], "Binary search on an answer requires a monotonic false-to-true boundary in the searched order.", ["binary_search_on_nonmonotonic_predicate"]),
